  replayController=mountDemoReplay({host:$('demo-replay-result'),getContext:prepareContext,getNetwork:()=>router.network,getBuild:()=>build.applicationSha256,search:q=>replayClient.route(q),name,onReturn:showView,loadIncidents:()=>loadIncidentLog()});
  services=mountServices({host:$('services-host'),noticeHost:$('services-entry'),loadIncidents:()=>loadIncidentLog(),getContext:()=>({active:companion.getActive(),input}),onReplay:incident=>replayController.run(incident),onOpenServices:()=>showView('facilities')});
